Import ListNotations. Open Scope Z_scope.

Abbreviation RSEGS := Plain.M.loaded_segments.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section Top.
  Context {AC : AllocCeiling} {RRND : RunRandom}.
  Context {fx : FPState} {AMB : Amb}.
  Variable MI : MallocIface SEGS L.
  Variable AINV0 : AS MI -> LibIface.mem -> Model -> Prop.
  Variables (TIGHT FRESH44 : AS MI -> Prop).
  Hypothesis DM : drv_mallocT MI AINV0 TIGHT FRESH44.

  Variable sp0 : word.
  Variable a0s : list byte.
  Variable envv : list (list byte).
  Variable tid : word.
  Variable rdraw : EntryDraw.
  Variable regs0 : bvmap 5 word.
  Variable mem0 : word -> option byte.
  Variables brk mbase : word.
  Variable fs0 : Fs.
  Variable stdin0 : InputStream.
  Hypothesis Hva : valid_argv [a0s; dot_path].
  Hypothesis Hve : valid_envp envv.
  Hypothesis Hvsp : valid_sp sp0.
  Hypothesis Htid : (0 < bv_unsigned tid < 2 ^ 22)%Z.
  Hypothesis ME : main_entry sp0 rdraw [a0s; dot_path] envv a_uid a_hwcap tid regs0 mem0.
  Hypothesis Hbrk : valid_brk RSEGS brk.

  Hypothesis HAC : (alloc_ceiling = bv_unsigned sp0 - 8388608)%Z.
  Hypothesis HRR : (rr_canary = bv_unsigned (canary rdraw))%Z.
  Hypothesis HRS : (rr_secret = rr_secret_of (ed_random rdraw))%Z.

  Let SPlo : (0x7fff80000000 <= bv_unsigned sp0)%Z := proj1 Hvsp.
  Let SPhi : (bv_unsigned sp0 <= 0x800000000000)%Z := proj1 (proj2 Hvsp).
  Let SPal : (bv_unsigned sp0 mod 16 = 0)%Z := proj2 (proj2 Hvsp).
  #[local] Notation SP0 := (bv_unsigned sp0).
  #[local] Notation TID := (bv_unsigned tid).
  #[local] Notation P1 := (bv_unsigned (p1 sp0 a0s dot_path envv)).
  #[local] Notation model0 := (S1RFront.model0 sp0 a0s dot_path envv tid brk mbase fs0 stdin0).
  #[local] Notation model1d := (S1RFront.model1d sp0 a0s dot_path envv tid brk mbase fs0 stdin0).

  Lemma p1_facts : SP0 <= P1 /\ P1 + Z.of_nat (length dot_path) + 1 < 2 ^ 63.
